import unicodedata


def slugify(s):
    # Decompose unicode characters (e.g. õ -> o + combining mark) and
    # drop any characters that cannot be encoded as ASCII.
    s = unicodedata.normalize('NFKD', s)
    s = s.encode('ascii', 'ignore').decode('ascii')
    s = s.lower()
    # Replace any run of non-alphanumeric characters with a single '-'.
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            if out and out[-1] != '-':
                out.append('-')
    # Trim a trailing '-' if present.
    if out and out[-1] == '-':
        out.pop()
    return ''.join(out)

